#include <stdio.h>
int main(void) {
    int n, stack[1000];
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < n; i++) scanf("%d", &stack[i]);
    for (int i = n - 1; i >= 0; i--) printf("%s%d", i == n - 1 ? "" : " ", stack[i]);
    printf("\n");
    return 0;
}

starter_code.C++:
#include <iostream>
#include <stack>
using namespace std;
int main() {
    int n, value; cin >> n;
    stack<int> st;
    for (int i = 0; i < n; i++) { cin >> value; st.push(value); }
    bool first = true;
    while (!st.empty()) { if (!first) cout << " "; cout << st.top(); st.pop(); first = false; }
    cout << endl;
    return 0;
}

